export function createSdkError(code, message) {
    const error = new Error(`${code}: ${message}`);
    error.name = 'AuthMiniSdkError';
    error.code = code;
    return error;
}
export function createRequestError(status, payload) {
    const code = typeof payload?.error === 'string' ? payload.error : 'request_failed';
    const error = createSdkError('request_failed', typeof payload?.error === 'string'
        ? payload.error
        : `Request failed with status ${status}`);
    error.status = status;
    if (payload) {
        Object.assign(error, payload);
    }
    if (!('error' in error)) {
        error.error = code;
    }
    return error;
}
